// 1×1 transparent PNG used as an immediate placeholder response when an
// animated/GIF render would otherwise serialize on the foreground request
// (C-F5). The actual GIF is generated by the background function and
// served via blob cache on subsequent fetches.
//
// 72 bytes. Decoded from a static base64 literal at module load — no I/O.
const PLACEHOLDER_BASE64 =
  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR4nGMAAQAAAAUAAQAgAAAAAlfwAAAAAElFTkSuQmCC";

export const PLACEHOLDER_PNG: Buffer = Buffer.from(PLACEHOLDER_BASE64, "base64");
export const PLACEHOLDER_CONTENT_TYPE = "image/png";
